INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d4c559b31fae71400d51ba9fe66160d5967ce6ca/content/books/zizhi-tongjian/vol-286/year-0947/part-02/sources/library/jiuwudaishi-085-947-january/source.txt", "note": "《旧五代史》卷八十五，段落 jiu-wudaishi-205deb4a7860-p002052；EPUB电子本，纸本及异文待核", "id": "548fcb32-173b-54f8-a340-102667e40687"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5d9d0eaf47ddcb551bf8ebe17a51e9f9ee98221/content/books/zizhi-tongjian/vol-286/year-0947/part-01/sources/library/tongjian-286-947-capital-entry/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003394；电子底本待考，分段待核", "id": "257c63a2-9485-520b-9ee6-781b3793539a"}, {"title": "辽史·卷四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5d9d0eaf47ddcb551bf8ebe17a51e9f9ee98221/content/books/zizhi-tongjian/vol-286/year-0947/part-01/sources/library/liaoshi-004-947-january/source.txt", "note": "《辽史》卷四，段落 liaoshi-7cd182a20e67-p000579；EPUB电子本，纸本及异文待核", "id": "e7449583-ec7a-55df-bb14-13daf37aa21c"}, {"title": "新五代史·卷二十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f475a8bdeb3fc70a41e5ca601f675229b6c6bfc4/content/books/zizhi-tongjian/vol-285/year-0946/part-08/sources/library/xinwudaishi-029-jing-capture/source.txt", "note": "《新五代史》卷二十九，段落 xin-wudaishi-b08f244b9241-p001071；EPUB电子本，纸本及异文待核", "id": "d28a7cc9-8d00-5844-80e4-dfd4cee62d73"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨承贵", "aliases": ["楊承貴", "杨承勋", "楊承勛", "楊承勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远之子。940年受父亲派遣围范延光私宅，逼其自尽，随后把范延光推入河中。《新五代史》相关执行者写杨承勋，姓名异说未裁定，不自动合并。生卒年未载。", "biography": null, "status": "draft", "id": "daf29c5e-0a0a-5cc1-aa88-e64404212a3c"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "杨承信", "aliases": ["楊承信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。《资治通鉴》称他为次子，938年五月与杨承祚同获优厚任官，具体官名未载。", "biography": null, "status": "draft", "id": "70bde002-fc6d-5293-9fb1-214458b656a6"}, {"name": "高勋", "aliases": ["高勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阁门使。946年十二月丙寅，杜重威派他向契丹送降表，耶律德光赐诏接受。与军将关勋分别识别；生卒年本批未核。", "biography": null, "status": "draft", "id": "ea4f636d-1bb8-5b40-a94d-0da7caf7ebea"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "傅住儿", "aliases": ["傅住兒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月耶律德光派张彦泽领二千骑先取大梁，让傅住儿任都监。姓名展示用简体儿，原文傅住兒保留；生卒年本批未核。", "biography": null, "status": "draft", "id": "12d197f3-4308-5bdc-8f6b-0f011bde8459"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "史匡威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史建瑭的儿子。947年契丹进入大梁后，以彰义节度使身份据守泾州，拒绝服从契丹命令。生卒年未载。", "biography": null, "status": "draft", "id": "33a282a4-7b28-5de0-8277-87347a12c935"}, {"name": "史建瑭", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“梁军围攻潞州，晋军出兵救援”中为救援将领。", "biography": null, "status": "draft", "id": "81052d96-db71-5a39-bbe0-c04154f90a17"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杨承勋被带到大梁，耶律德光以杀父和背叛契丹为由命人杀死他", "start_year": 947, "end_year": 947, "time_original": "947年正月戊子", "dynasty": "五代十国", "description": "杨承勋被带到大梁，耶律德光以杀父和背叛契丹为由命人杀死他。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "542e2444-19d2-50f9-950a-63156d7d9fdd"}, {"title": "耶律德光不久任命杨承信为平卢节度使，把其父旧兵交给他", "start_year": 947, "end_year": 947, "time_original": "947年正月戊子之后不久，具体日未载", "dynasty": "五代十国", "description": "耶律德光不久任命杨承信为平卢节度使，把其父旧兵交给他。", "phases": [], "location_name": "平卢军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "af7f505c-fe2a-5b00-ab42-036ce958c67b"}, {"title": "高勋向耶律德光控告张彦泽杀其家人，张和傅住儿被一同锁押", "start_year": 947, "end_year": 947, "time_original": "947年正月己丑处死前，具体日未载", "dynasty": "五代十国", "description": "高勋向耶律德光控告张彦泽杀其家人，张和傅住儿被一同锁押。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "97ee8b17-b8e3-5c78-8393-1889c418a0e1"}, {"title": "耶律德光向百官公布张彦泽罪状并问是否当死，官员赞同，百姓也递状控告", "start_year": 947, "end_year": 947, "time_original": "947年正月己丑前", "dynasty": "五代十国", "description": "耶律德光向百官公布张彦泽罪状并问是否当死，官员赞同，百姓也递状控告。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "941e749b-5027-5d17-b69b-11f42cc3a575"}, {"title": "张彦泽、傅住儿在北市被处死，高勋