SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "杨承勋被带到大梁，耶律德光以杀父和背叛契丹为由命人杀死他。", "citation": "卷286·天福十二年（947年正月）·zztj-v286-y0947-p004·原文件第9行", "note": "原文：戊子，执郑州防御使杨承勋至大梁，责以杀父叛契丹，命左右脔食之。；核对说明：杨承勋初名杨承贵已在944年传记校核，复用稳定主体。杀父是契丹主指责，不能覆盖944年李守贞命都将杀杨光远的记载。脔食是肢解并食肉，不扩写具体参与者姓名。", "status": "draft", "id": "9ef96e8e-3d74-5420-af7b-fb5a2c514188", "subject_id": "542e2444-19d2-50f9-950a-63156d7d9fdd", "source_id": "257c63a2-9485-520b-9ee6-781b3793539a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "947年正月戊子", "citation": "卷286·天福十二年（947年正月）·zztj-v286-y0947-p004·原文件第9行", "note": "原文：戊子，执郑州防御使杨承勋至大梁，责以杀父叛契丹，命左右脔食之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6dcc58f1-4d0d-5b45-875d-9b2754a41771", "subject_id": "542e2444-19d2-50f9-950a-63156d7d9fdd", "source_id": "257c63a2-9485-520b-9ee6-781b3793539a"}, {"subject_table": "person", "field_path": "description", "claim_text": "杨承贵：以郑州防御使身份被捕处死。", "citation": "卷286·天福十二年（947年正月）·zztj-v286-y0947-p004·原文件第9行", "note": "原文：戊子，执郑州防御使杨承勋至大梁，责以杀父叛契丹，命左右脔食之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "54f850ec-26ea-5c92-8e11-fb5843ecf13f", "subject_id": "daf29c5e-0a0a-5cc1-aa88-e64404212a3c", "source_id": "257c63a2-9485-520b-9ee6-781b3793539a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杨承贵：以郑州防御使身份被捕处死。", "citation": "卷286·天福十二年（947年正月）·zztj-v286-y0947-p004·原文件第9行", "note": "原文：戊子，执郑州防御使杨承勋至大梁，责以杀父叛契丹，命左右脔食之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "fbd85268-a118-5d4f-95f2-f495d5614ff8", "subject_id": "8ef64439-d401-554d-b374-01bc49dea128", "source_id": "257c63a2-9485-520b-9ee6-781b3793539a"}, {"subject_table": "person", "field_path": "description", "claim_text": "耶律德光：以杀父和叛契丹指责杨承勋，命人处死。", "citation": "卷286·天福十二年（947年正月）·zztj-v286-y0947-p004·原文件第9行", "no